]



\node[box] (thm_Teich_chart) 
  {Theorem~\ref{thm:Teich.chart}\\\((\cT(G),\cC_G)_G\) is a chart of \(\cTp\)};

\node[box, left=of thm_Teich_chart, yshift=-6pt] (def_circ_foli_map) 
  {Definition~\ref{def:circ.foli.map.}\\Circular foliation map \(\cC_G\)};

\node[box, right=of thm_Teich_chart] (cor_embed) 
  {Corollary~\ref{cor:embed}\\\(\cC_G:\cT_{\rm u.t.}(S,\up) \hookrightarrow \cMFp\)};

\node[box, above=of thm_Teich_chart, yshift=-12pt] (cor_homeo_TS_shear_radius) 
  {Corollary~\ref{cor:homeo.TS.shear.radius}\\Shear--radius on \(\cT(G)\)};

\node[box, left=of cor_homeo_TS_shear_radius, yshift=-7pt] (prop_edge_leng) 
  {Proposition~\ref{prop:edge.leng.homeo.}\\Edge parametrizations are  homeomorphisms};

\node[box, right=of cor_homeo_TS_shear_radius] (thm_homeo_MFp_shear_radius) 
  {Theorem~\ref{thm:homeo.MFp.shear.radius}\\Shear--radius on \(\cMFp\)};

\node[box, below=of thm_Teich_chart, yshift=8pt] (thm_asym) 
  {Theorems~\ref{thm:asym.behavior} \&~\ref{thm:asym.behavior1}\\Asymptotic limits};

\node[box, left=of thm_asym] (def_part_stret) 
  {Definition~\ref{def:part.stret.}\\Partial stretch / anti-stretch};

\node[box, right=of thm_asym, yshift=12pt] (angle_results) 
  {Proposition~\ref{prop:angle.face} \& Theorem~\ref{thm:adm.cone.angle}\\Max cone angle in \(\cT(G)\) and \(\cT_{\rm u.t.}(S,\up)\)};


\begin{scope}[on background layer]



\path let \p1 = (prop_edge_leng.west), \p2 = (cor_homeo_TS_shear_radius.north) 
        in coordinate (TopLeft) at (\x1 - 10pt, \y2 + 15pt);

\path (thm_homeo_MFp_shear_radius.north east) ++(10pt, 15pt) coordinate (TopRight);

\path (thm_homeo_MFp_shear_radius.south east) ++(10pt, -10pt) coordinate (StepRightTop);

\path ($(thm_Teich_chart.east)!0.5!(cor_embed.west)$) ++(-4pt, 0pt) coordinate (MidX);
  \coordinate (StepInnerCorner) at (MidX |- StepRightTop);

\path (thm_Teich_chart.south -| MidX) ++(0pt, -10pt) coordinate (StepRightBottom);

\path (def_circ_foli_map.south west) ++(-10pt, -10pt) coordinate (BottomLeft);

\draw[gray!80, dashed, fill=gray!5, rounded corners=5pt] 
    (TopLeft) -- (TopRight) -- (StepRightTop) -- (StepInnerCorner) -- (StepRightBottom) -- (BottomLeft) -- cycle;

\node[anchor=north west, text=gray!80, font=\bfseries\small, inner sep=0pt, xshift=15pt, yshift=-5pt] 
    at (TopLeft) {Sections~\ref{sec:circ.foli.coor.app.}};




\path (thm_asym.north) ++(0, 10pt) coordinate (top_sec6);
  \node[group={subsec:application}, fit=(def_part_stret) (thm_asym) (top_sec6)] {};

\path (cor_embed.north) ++(0, 10pt) coordinate (top_sec7);
  \node[group={sec:max.cone.angle}, fit=(cor_embed) (angle_results) (top_sec7)] {};

\end{scope}
\draw[dep] (def_circ_foli_map) -- (thm_Teich_chart);
\draw[dep] (prop_edge_leng) -- (thm_Teich_chart);
\draw[dep] (thm_Teich_chart) -- (cor_embed);
\draw[dep] (thm_Teich_chart) -- (cor_homeo_TS_shear_radius);
\draw[dep] (thm_homeo_MFp_shear_radius) -- (cor_homeo_TS_shear_radius);
\draw[use] (def_circ_foli_map) -- (def_part_stret);
\draw[dep] (def_part_stret) -- (thm_asym);
\draw[dep] (thm_Teich_chart) -- (thm_asym);
\draw[dep] (thm_Teich_chart) -- (angle_results);

\end{tikzpicture}
}
\caption{Dependency graph of the main theorems, definitions, and propositions, grouped by section. 
Solid arrows indicate logical implications, while dashed arrows indicate conceptual dependencies. 
The layout highlights the progression from the definition of the circular foliation map to its asymptotic and geometric consequences.}
\label{fig:pipeline}
\end{figure}

